  "evidence": [
   {
    "quote": "Return false for has_column_privilege() checks on non-existent or dropped columns when using attribute numbers",
    "source": "PostgreSQL 14 release notes: Migration to Version 14",
    "release_of_change": "14"
   }
  ]
 },
